#include <list>
#include <algorithm>

int main() {
    std::list<int> l1 = {1, 5, 9};
    std::list<int> l2 = {2, 4, 10};

    // Merge l2 into l1 (O(N) operation)
    l1.merge(l2);

    // l1 is now {1, 2, 4, 5, 9, 10}
    // l2 is empty

    // l1.merge(l2, std::greater<int>()); // Requires both lists sorted descendingly
}
